async function promotion(){loadingPage('Loading promotions…','profile');try{const d=await api('/.netlify/functions/social-promotions');const types=[['viral_profile','Viral Profile'],['viral_video','Viral Video'],['photo','Photo Promotion'],['relationship','Relationship Promotion'],['business','Business Promotion'],['music','Music Promotion'],['follower_growth','Follower Growth']];const rows=(d.promotions||[]).map(p=>'<article class="aam-social-card"><div class="aam-social-muted">MANAGER PROMOTION · '+esc(p.status.replaceAll('_',' '))+'</div><h3>'+esc(p.title)+'</h3><img class="aam-social-preview" src="'+esc(p.media_url)+'" alt="Advert picture"><p>'+esc(p.description)+'</p><p class="aam-social-muted">'+esc((types.find(x=>x[0]===p.promotion_type)||[])[1]||p.promotion_type)+' · '+Number(p.requested_days)+' days</p>'+(p.price_coins?'<p>Price: <strong>'+Number(p.price_coins).toLocaleString()+' Money Coins</strong></p>':'<p class="aam-social-muted">Price pending review.</p>')+(p.status==='awaiting_payment'&&p.provider_status==='ready'?'<button class="aam-social-btn" onclick="AAMSocial.payPromotion(\''+p.id+'\')">Pay with Money Coins</button>':'')+(p.admin_note?'<p>'+esc(p.admin_note)+'</p>':'')+'<p class="aam-social-muted">Provider: '+esc(p.provider_status.replaceAll('_',' '))+'</p></article>').join('');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.open(\'profile\')">← Profile</button><h2>Manager Promotion</h2><p>Prepare an advert for your profile, picture, video, relationship, business or music.</p><div class="aam-social-balance">'+Number(d.promotion_balance||0).toLocaleString()+' Money Coins</div><p class="aam-social-muted">Promotion Balance is your purchased Money Coins. Free Coins are not accepted. Your advert is reviewed before pricing. No coins are deducted on submission.</p><label>Promotion type</label><select class="aam-social-field" id="aamPromoType">'+types.map(x=>'<option value="'+x[0]+'">'+x[1]+'</option>').join('')+'</select><label>Advert title</label><input class="aam-social-field" id="aamPromoTitle" maxlength="100" placeholder="Advert title"><label>Description</label><textarea class="aam-social-field" id="aamPromoDescription" maxlength="2000" placeholder="Describe your advert"></textarea><label>Advert picture</label><input class="aam-social-field" id="aamPromoImage" type="file" accept="image/jpeg,image/png,image/webp"><label>Profile or destination link (optional)</label><input class="aam-social-field" id="aamPromoDestination" maxlength="500" placeholder="Your profile or destination link"><label>Requested duration</label><select class="aam-social-field" id="aamPromoDays"><option value="1">1 day</option><option value="3">3 days</option><option value="7" selected>7 days</option><option value="14">14 days</option><option value="30">30 days</option></select><button class="aam-social-btn" onclick="AAMSocial.submitPromotion()">Submit advert for review</button><p class="aam-social-muted">Campaigns will not run until the advertising provider is connected and approval is complete.</p></div><h3>Your promotions</h3>'+(rows||'<div class="aam-social-card aam-social-muted">No promotions submitted yet.</div>'),'profile');}catch(e){notice(e.message);}}
async function submitPromotion(){const file=document.getElementById('aamPromoImage')?.files?.[0];if(!file)return notice('Choose your advert picture.');const title=document.getElementById('aamPromoTitle')?.value||'',description=document.getElementById('aamPromoDescription')?.value||'';if(title.trim().length<3||description.trim().length<5)return notice('Enter an advert title and description.');try{const signed=await api('/.netlify/functions/social-promotions','POST',{action:'sign_upload',mime_type:file.type});const uploaded=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;const d=await api('/.netlify/functions/social-promotions','POST',{action:'create',promotion_type:document.getElementById('aamPromoType').value,title,description,media_path:signed.path,destination_url:document.getElementById('aamPromoDestination').value||'',requested_days:Number(document.getElementById('aamPromoDays').value||7)});notice(d.message||'Advert submitted for review.');promotion();}catch(e){notice(e.message||'Could not submit advert.');}}
async function payPromotion(id){if(!confirm('Pay the approved advert price using Money Coins? Free Coins cannot be used.'))return;try{const d=await api('/.netlify/functions/social-promotions','POST',{action:'pay',promotion_id:id});notice(d.message||'Payment recorded.');promotion();}catch(e){notice(e.message);}}
