function dock(active='home'){if(!customer()||!token()||!root()||!document.querySelector('.container'))return;let n=document.getElementById('aamSocialDock');if(!n){n=document.createElement('nav');n.id='aamSocialDock';n.setAttribute('aria-label','Social navigation');document.body.appendChild(n);}n.innerHTML=[['home','⌂','HOME'],['status','◌','STATUS'],['upload','＋','POST'],['chat','▤','INBOX'],['profile','◉','PROFILE']].map(([id,icon,label])=>'<button class="'+(active===id?'active':'')+'" onclick="AAMSocial.open(\''+id+'\')"><div style="font-size:19px">'+icon+'</div>'+label+'</button>').join('');let tools=document.getElementById('aamSocialToolsDock');if(!tools){tools=document.createElement('div');tools.id='aamSocialToolsDock';tools.setAttribute('aria-label','Tools section');document.body.appendChild(tools);}tools.innerHTML='<button type="button" onclick="AAMSocial.open(\'tools\')"><span aria-hidden="true">▦</span> TOOLS</button>'; }
function mount(html,active){const a=root();if(!a)return;a.innerHTML='<header class="topbar"><div class="brand">All Ads Manager</div><div class="aam-top-actions">'+(adminToken()?'':'<button class="aam-notify-btn" id="aamNotifyBtn" onclick="AAMSocial.notifications()">♢</button>')+'<button class="tiny-admin" aria-label="Admin login" title="Admin login" onclick="AAMSocial.open(\'dashboard\')"></button></div></header><main class="container" id="aamSocialRoot"><div class="aam-social-wrap">'+html+'</div></main>';dock(active);updateNotificationBadge();}
function coinPackagesMarkup(){const amounts=[500,1000,2000,5000,10000,20000,50000];return '<details class="aam-social-card"><summary><strong>Buy Money Coins</strong></summary><p class="aam-social-muted">1 coin = ₦1. Minimum purchase ₦500. Money Coins and Free Coins are kept separately. Free Coins are only for watching paid videos. Money Coins can unlock videos, pay for Manager Promotion, and add pictures during video calls. Your tools wallet is separate.</p><label>Email for this Paystack payment only</label><input class="aam-social-field" id="aamCoinEmail" type="email" autocomplete="email" placeholder="Receipt email"><p class="aam-social-muted">This is only for your payment receipt. It is not required for your All Ads Manager account.</p><label>Payment method</label><select class="aam-social-field" id="aamCoinMethod"><option value="bank_transfer">Bank Transfer</option><option value="card">ATM / Card</option></select><div class="aam-coin-packages">'+amounts.map(n=>'<button class="aam-social-btn secondary" type="button" onclick="AAMSocial.buyCoins('+n+')">₦'+n.toLocaleString()+' · '+n.toLocaleString()+' coins</button>').join('')+'</div></details>';}
async function buyCoins(amount){const email=document.getElementById('aamCoinEmail')?.value.trim()||'',method=document.getElementById('aamCoinMethod')?.value||'bank_transfer';if(!email)return notice('Enter your email for the Paystack receipt.');try{const r=await fetch('/.netlify/functions/social-coin-create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token(),amount,email,method})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not start coin purchase.');if(!d.authorization_url)throw new Error('Paystack did not return a payment link.');window.location.href=d.authorization_url;}catch(e){notice(e.message||'Could not start coin purchase.');}}
async function home(){if(!customer())return;loadingPage('Loading your feed…','home');try{const d=await api('/.netlify/functions/social-core');notificationSoundChoice=Number(d.preferences?.notification_sound||1);if(!d.profile?.adult_confirmed_at){mount('<div class="aam-social-card"><h2>Adults only · 18+</h2><p>This social community is for adults aged 18 or older.</p><p>By continuing, you confirm that you are at least 18 years old.</p><button class="aam-social-btn" onclick="AAMSocial.confirmAdult()">I confirm I am 18 or older</button></div>','home');return;}const f=await api('/.netlify/functions/social-feed');mount('<section class="aam-wallet-card"><div class="aam-wallet-head"><span>MY WALLET</span><span class="aam-wallet-icon">◈</span></div><div class="aam-wallet-total-label">TOTAL COINS</div><div class="aam-wallet-total">'+Number(d.coin_balance||0).toLocaleString()+'</div><div class="aam-wallet-grid"><div class="aam-wallet-tile"><span>FREE COINS</span><strong>'+Number(d.free_coin_balance||0).toLocaleString()+'</strong></div><div class="aam-wallet-tile"><span>MONEY COINS</span><strong>'+Number(d.purchased_coin_balance||0).toLocaleString()+'</strong></div><div class="aam-wallet-tile aam-wallet-wide"><span>PROMOTION BALANCE</span><strong>'+Number(d.money_coin_balance||0).toLocaleString()+' <small>Money Coins</small></strong></div></div><button class="aam-wallet-action" onclick="AAMSocial.openPromotion()">Manager Promotion <span>→</span></button></section>'+coinPackagesMarkup()+'<div class="aam-social-card"><h3>Find friends</h3><input class="aam-social-field" id="aamDiscoverQuery" maxlength="40" placeholder="Search by display name"><button class="aam-social-btn" onclick="AAMSocial.discover()">Search</button><div id="aamDiscoverResults"></div></div><h2>Home</h2><div id="aamFeedRefreshHint" class="aam-feed-refresh-hint" aria-live="polite">↓ Pull down to refresh</div><div id="aamSocialPosts" class="aam-social-feed">'+(f.posts||[]).map(postCard).join('')+'</div>','home');setupFeedRefresh();if(f.source_errors?.length)console.warn('[AAM] Dailymotion feed:',f.source_errors.join('; '));}catch(e){mount('<div class="aam-social-card"><h2>Home feed</h2><p>'+esc(e.message)+'</p><button class="aam-social-btn" onclick="AAMSocial.open(\'dashboard\')">←</button></div>','home');}}
let aamFeedRefreshBusy=false,aamFeedTouchStartY=0,aamFeedTouchStartTop=0;
async function refreshHomeFeed(){if(aamFeedRefreshBusy)return;aamFeedRefreshBusy=true;const hint=document.getElementById('aamFeedRefreshHint'),feed=document.getElementById('aamSocialPosts');if(hint)hint.textContent='Refreshing videos…';try{const f=await api('/.netlify/functions/social-feed');if(!feed)return;feed.innerHTML=(f.posts||[]).map(postCard).join('');if(f.source_errors?.length)console.warn('[AAM] Dailymotion feed:',f.source_errors.join('; '));if(hint)hint.textContent='Updated';}catch(e){if(hint)hint.textContent='Could not refresh. Pull down to try again.';}finally{aamFeedRefreshBusy=false;setTimeout(()=>{const el=document.getElementById('aamFeedRefreshHint');if(el&&el.textContent==='Updated')el.textContent='↓ Pull down to refresh';},1400);}}
function setupFeedRefresh(){const feed=document.getElementById('aamSocialPosts');if(!feed||feed.dataset.refreshBound)return;feed.dataset.refreshBound='1';feed.addEventListener('touchstart',e=>{if(e.touches?.length===1){aamFeedTouchStartY=e.touches[0].clientY;aamFeedTouchStartTop=feed.scrollTop;}},{passive:true});feed.addEventListener('touchend',e=>{const y=e.changedTouches?.[0]?.clientY;if(y!=null&&aamFeedTouchStartTop<=1&&y-aamFeedTouchStartY>72)refreshHomeFeed();},{passive:true});feed.addEventListener('wheel',e=>{if(feed.scrollTop<=0&&e.deltaY<-70)refreshHomeFeed();},{passive:true});}
let aamFocusedVideo=null;
function closeFocusedVideo(){if(!aamFocusedVideo)return;const s=aamFocusedVideo;try{if(s.placeholder?.parentNode)s.placeholder.parentNode.replaceChild(s.media,s.placeholder);else s.media.remove();}catch{}s.overlay?.remove();aamFocusedVideo=null;document.body.classList.remove('aam-video-focus-open');}
function focusPostVideo(id){closeFocusedVideo();const card=[...document.querySelectorAll('.aam-social-feed-item')].find(x=>x.dataset.postId===String(id));const media=card?.querySelector('.aam-social-external-video,.aam-social-media');if(!media)return notice('Video is not available.');const placeholder=document.createElement('div');placeholder.className='aam-video-focus-placeholder';media.parentNode.insertBefore(placeholder,media);const overlay=document.createElement('section');overlay.className='aam-video-focus-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Full-screen video');const close=document.createElement('button');close.type='button';close.className='aam-video-focus-close';close.setAttribute('aria-label','Close full-screen video');close.textContent='×';close.addEventListener('click',closeFocusedVideo);const rail=document.createElement('div');rail.className='aam-video-focus-rail';rail.setAttribute('aria-label','Video actions');const like=document.createElement('button');like.type='button';like.className='aam-video-focus-action';like.innerHTML='♡<small>Like</small>';like.addEventListener('click',async()=>{try{const d=await api('/.netlify/functions/social-interactions','POST',{action:'like',post_id:id});like.classList.toggle('is-active',!!d.liked);like.innerHTML=(d.liked?'♥':'♡')+'<small>Like</small>';}catch(e){notice(e.message);}});const comment=document.createElement('button');comment.type='button';comment.className='aam-video-focus-action';comment.innerHTML='▢<small>Comment</small>';const share=document.createElement('button');share.type='button';share.className='aam-video-focus-action';share.innerHTML='↗<small>Share</small>';share.addEventListener('click',()=>sharePost(id));const commentPanel=document.createElement('div');commentPanel.className='aam-video-focus-comments';commentPanel.id='aamComments-'+id;comment.addEventListener('click',async()=>{commentPanel.classList.toggle('is-open');if(commentPanel.dataset.loaded!=='1'){await comments(id);commentPanel.dataset.loaded='1';}});const meta=document.createElement('div');meta.className='aam-video-focus-meta';const creator=card?.querySelector('.aam-social-creator strong')?.textContent||'All Ads Manager';const caption=card?.querySelector(':scope > p')?.textContent||'';meta.innerHTML='<strong>'+esc(creator)+'</strong>'+(caption?'<p>'+esc(caption)+'</p>':'');rail.append(like,comment,share);overlay.append(close,media,meta,rail,commentPanel);document.body.appendChild(overlay);aamFocusedVideo={media,placeholder,overlay};document.body.classList.add('aam-video-focus-open');}
function postCard(p){const locked=!!p.locked_video;const follow=p.creator?.id?'<div class="aam-social-creator-actions">'+(p.is_following?'<span class="aam-social-muted">Following</span>':'<button class="aam-social-btn secondary" onclick="AAMSocial.follow(&quot;'+esc(p.creator.id)+'&quot;)">Follow</button>')+'<button class="aam-social-btn secondary" onclick="AAMSocial.startChat(&quot;'+esc(p.creator.id)+'&quot;)">Message</button></div>':'';const media=locked?'<div class="aam-social-locked">'+(p.thumbnail_url?'<img class="aam-social-thumbnail" src="'+esc(p.thumbnail_url)+'" alt="Locked video preview">':'')+'<div><strong>🔒 Paid video</strong><p>Watch this video for 1 coin (₦1).</p><button class="aam-social-btn" onclick="AAMSocial.unlockVideo(&quot;'+esc(p.id)+'&quot;)">Watch for 1 coin (₦1)</button></div></div>':(p.media_type==='text'?'<div class="aam-social-text-post" style="background:'+esc(p.background_color||'#172554')+'">'+esc(p.caption||'')+'</div>':(p.provider==='dailymotion'?'<div class="aam-social-external-video"><iframe src="'+esc(p.media_url||'')+'" title="'+esc(p.caption||'Video')+'" allow="autoplay; fullscreen; picture-in-picture; encrypted-media" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe></div>':(p.media_type==='video'?'<video class="aam-social-media" controls playsinline preload="none" src="'+esc(p.media_url||'')+'"></video>':'<img class="aam-social-media" loading="lazy" src="'+esc(p.media_url||'')+'" alt="Post image">')));return '<article data-post-id="'+esc(p.id)+'" class="aam-social-card aam-social-feed-item"><div class="aam-social-creator">'+(p.creator?.avatar_url?'<img class="aam-social-feed-avatar" src="'+esc(p.creator.avatar_url)+'" alt="">':'')+'<strong>'+esc(p.creator?.name||'Friend')+(p.verified?'<span class="aam-verified" aria-label="Verified">✓</span>':'')+'</strong>'+(p.creator?.id?'':'<button class="aam-social-btn secondary" onclick="AAMSocial.viewAdminProfile()">View friend</button>')+(p.follower_count!=null?'<span class="aam-social-muted">'+formatCount(p.follower_count)+' followers · 0 following</span>':'')+follow+'</div><div class="aam-social-muted">'+new Date(p.created_at).toLocaleString()+'</div>'+media+(!locked&&(p.provider==='dailymotion'||p.media_type==='video')?'<button type="button" class="aam-social-btn secondary aam-video-focus-trigger" onclick="AAMSocial.focusVideo(&quot;'+esc(p.id)+'&quot;)">⛶ Full screen</button>':'')+(p.caption?'<p>'+esc(p.caption)+'</p>':'')+'<div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.like(&quot;'+esc(p.id)+'&quot;)">'+(p.liked?'♥ Liked':'♡ Like')+' · '+formatCount(p.like_count||0)+'</button>'+(p.comments_enabled?'<button class="aam-social-btn secondary" onclick="AAMSocial.comments(&quot;'+esc(p.id)+'&quot;)">Comments · '+formatCount(p.comment_count||0)+'</button>':'')+'<button class="aam-social-btn secondary" onclick="AAMSocial.sharePost(&quot;'+esc(p.id)+'&quot;)">Share in chat</button><button class="aam-social-btn secondary" onclick="AAMSocial.sharePostLink(&quot;'+esc(p.id)+'&quot;)">Share link</button></div><div id="aamComments-'+esc(p.id)+'"></div></article>';}
