async function openProfileCamera(){if(!navigator.mediaDevices?.getUserMedia){document.getElementById('aamAvatarFile')?.click();return notice('Camera is unavailable. Choose a photo from your gallery.');}try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'user'}},audio:false});document.getElementById('aamProfileCameraModal')?.remove();const modal=document.createElement('div');modal.id='aamProfileCameraModal';modal.className='aam-profile-camera-modal';modal.innerHTML='<div class="aam-profile-camera-panel"><header><button type="button" aria-label="Close camera" id="aamProfileCameraClose">←</button><strong>Profile photo</strong><span></span></header><video id="aamProfileCameraVideo" autoplay playsinline muted></video><div class="aam-profile-camera-actions"><button type="button" id="aamProfileCapture">● Capture photo</button><button type="button" id="aamProfileUseGallery">▧ Gallery</button></div></div>';document.body.appendChild(modal);const video=modal.querySelector('video');video.srcObject=stream;await video.play();const stop=()=>{stream.getTracks().forEach(t=>t.stop());modal.remove();};modal.querySelector('#aamProfileCameraClose').onclick=stop;modal.querySelector('#aamProfileUseGallery').onclick=()=>{stop();document.getElementById('aamAvatarFile')?.click();};modal.querySelector('#aamProfileCapture').onclick=()=>{if(!video.videoWidth)return notice('Camera is starting. Try again.');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{stop();if(blob)uploadAvatarBlob(new File([blob],'profile-photo.jpg',{type:'image/jpeg'}));},'image/jpeg',.92);};}catch(e){notice(e.name==='NotAllowedError'?'Allow camera access to take your profile photo.':'Camera unavailable. Choose a photo from your gallery.');}}
